import requests

try:
    response = requests.get("https://example.com", timeout=2)
    response.raise_for_status()
except requests.exceptions.ConnectTimeout:
    print("The connection timed out and can be retried.")
except requests.exceptions.Timeout:
    print("The request timed out.")
except requests.exceptions.RequestException as error:
    print(f"Request failed: {error}")

import requests

response = requests.get("https://httpbin.org/status/404")
try:
    response.raise_for_status()
except requests.exceptions.HTTPError as error:
    print(error)

import requests

try:
    response = requests.get("https://example.com", timeout=1)
    response.raise_for_status()
except requests.exceptions.ConnectTimeout:
    print("The connection timed out; retrying is safe.")
except requests.exceptions.ReadTimeout:
    print("The server sent no data in time.")
except requests.exceptions.RequestException as error:
    print(f"Request failed: {error}")

